This implementation provides a robust, production-ready asynchronous job queue using **Redis** as the primary state store. It utilizes **Lua scripting** to ensure atomicity for `push` and `pop` operations, preventing race conditions common in distributed systems.

### Prerequisites
`npm install ioredis`

---

### 1. `src/types.ts`
```typescript
export type JobStatus = 'pending' | 'processing' | 'completed' | 'failed';

export interface Job<T> {
  id: string;
  data: T;
  status: JobStatus;
  attempts: number;
  maxAttempts: number;
  nextRun: number;
}

export type WorkerHandler<T> = (job: Job<T>) => Promise<void>;

export interface QueueOptions {
  queueName: string;
  maxAttempts?: number;
  visibilityTimeoutMs?: number;
}
```

