### 3. `src/JobQueue.ts`
```typescript
import { Redis } from 'ioredis';
import { Job } from './types';
import { v4 as uuidv4 } from 'uuid';

export class JobQueue<T> {
  constructor(private redis: Redis, private queueName: string) {}

  async push(data: T, maxAttempts: number = 3): Promise<string> {
    const job: Job<T> = {
      id: uuidv4(),
      data,
      status: 'pending',
      attempts: 0,
      maxAttempts,
      nextRun: Date.now(),
    };
    await this.redis.lpush(`${this.queueName}:pending`, JSON.stringify(job));
    return job.id;
  }

  async pop(): Promise<Job<T> | null> {
    const script = `
      local job = redis.call('rpop', KEYS[1])
      if job then
        redis.call('hset', KEYS[2], cjson.decode(job).id, job)
        return job
      end
      return nil
    `;
    const result = await this.redis.eval(script, 2, `${this.queueName}:pending`, `${this.queueName}:active`);
    return result ? JSON.parse(result as string) : null;
  }

  async complete(job: Job<T>): Promise<void> {
    await this.redis.hdel(`${this.queueName}:active`, job.id);
  }

  async fail(job: Job<T>): Promise<void> {
    await this.redis.hdel(`${this.queueName}:active`, job.id);
    if (job.attempts < job.maxAttempts) {
      job.attempts++;
      job.nextRun = Date.now() + Math.pow(2, job.attempts) * 1000;
      await this.redis.lpush(`${this.queueName}:pending`, JSON.stringify(job));
    } else {
      await this.redis.lpush(`${this.queueName}:dlq`, JSON.stringify(job));
    }
  }
}
```

