### 4. `src/Worker.ts`
```typescript
import { Job, WorkerHandler } from './types';
import { JobQueue } from './JobQueue';

export class Worker<T> {
  private running = false;
  private activeJobs = 0;

  constructor(
    private queue: JobQueue<T>,
    private handler: WorkerHandler<T>,
    private concurrency: number = 1
  ) {}

  async start() {
    this.running = true;
    while (this.running) {
      if (this.activeJobs < this.concurrency) {
        const job = await this.queue.pop();
        if (job) {
          this.activeJobs++;
          this.process(job);
        }
      }
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  private async process(job: Job<T>) {
    try {
      await this.handler(job);
      await this.queue.complete(job);
    } catch (e) {
      await this.queue.fail(job);
    } finally {
      this.activeJobs--;
    }
  }

  async shutdown() {
    this.running = false;
    while (this.activeJobs > 0) await new Promise((r) => setTimeout(r, 100));
  }
}
```

